          [value]="fromInput()['late-pct'] ?? ''"
          (input)="typeFrom('late-pct', $any($event.target).value)"
        />
        <label for="setting-policy-date">Policy date (blank: the sheet's today)</label>
        <input
          id="setting-policy-date"
