// button on it is refused with an error on the claim. A refused edit button takes no lock. The lock
// is kept in the store, so the editor is open again when its user re-loads the sheet.
// A steward may void a SETTLED claim within 7 days of its settlement by the sheet's today: it keeps
// its number and shows its frozen due, which leaves every total. Anyone else, or a later day, is
// refused with an error on the claim.
// Each claim shows its due-by, fixed when it was added (its date plus the terms of its person's grade
// in force on its date, or the sheet's terms when that grade has none), and whether it is overdue:
// OPEN with its due-by before the sheet's today. An overdue claim's due gains the sheet's late
// percent of its figure for every full 30 days it is overdue.
// A claim with a negative amount is a correction: it must name, by number, a SETTLED claim of the
// same person that it corrects, else it is refused. Its due has no floor and no late charge, and
// it shows the number it corrects.
// A clerk settling a claim whose due is above the clerk limit makes it PENDING. A PENDING claim
// counts like an OPEN one but is not bound by a statement: it shows its live figure. A steward
// approves it (SETTLED, its due fixed then) or rejects it with a reason (back to OPEN, bound again
// by the last statement); the user who opened it cannot approve it.
// Who may open, settle, void or move a claim is the sheet's permission matrix (see the settings).
// By default a steward can move a DRAFT, OPEN or PENDING claim to another person: it keeps its number and
// date, loses any figure a statement bound it to, and is listed first under its new person.
// An OPEN claim can be deferred to a date after the sheet's today (refused for a claim that is not
// OPEN, a date not after today, or a claim in a closed period). Until the sheet's today reaches that
// date it counts in no total, is not overdue, cannot be settled and is left unbound by a statement.
// Each claim shows its proofs count, raised by one with its proof button (refused for a SETTLED or
// VOID claim, or one in a closed period). A claim whose due is above the proof threshold in force on
// its date cannot be settled or approved while it has no proofs: refused with an error on the claim.
// An OPEN or PENDING claim can be reminded with its remind button, once per sheet-today: it shows
  imports: [Header, Holidays, PersonClaims, Periods, Rates, Roles, Settings, Summary],
  template: `
    <app-header
      [peopleCount]="people().length"
      [statuses]="statusSummary()"
      [dueTotal]="dueTotal()"
      [overdueTotal]="money(overdueTotals().cents)"
    />
    <app-rates [(rates)]="rates" />
    <app-roles />
    <app-settings [(floors)]="floors" [(latePcts)]="latePcts" [(policyDate)]="policyDate" [(caps)]="caps" />
    <app-periods [(periods)]="periods" [dues]="dues()" />
    <app-holidays />
    <section aria-labelledby="people-heading">
      <h2 id="people-heading">People</h2>
      <form aria-label="Person" (submit)="save($event)">
                  {{ watched().has(p.id) ? 'Unwatch' : 'Watch' }}
                </button>
              </td>
              <td>
                <app-person-claims
                  [personId]="p.id"
                  [personName]="p.name"
                  [claims]="claimsOf(p.id)"
                  [grades]="p.grades"
                  [rates]="rates()"
                  [floors]="floors()"
                  [latePcts]="latePcts()"
                  [policyDate]="policyDate()"
                  [periods]="periods()"
                  [selected]="selectedClaims()"
                  [people]="people()"
                  (saved)="claimSaved($event)"
                  (reassigned)="claimMoved($event)"
                  (selectedChange)="selectClaim($event.id, $event.on)"
                />
              </td>
              <td>
                <button
                  type="button"
                  [attr.data-testid]="'person-edit-' + p.id"
                  [attr.aria-label]="'Edit ' + p.name"
  /** The sheet's floors, dated: the one in force on a claim's date is the least its live due can be. */
  protected readonly floors = signal<DatedValue[]>([]);
  /** The sheet's caps, dated (blank: none): the one in force on the sheet's today is the most a
   *  person's due-total can be. */
  protected readonly caps = signal<DatedValue[]>([]);
  private readonly capCents = computed(() => {
    const cap = valueOn(this.caps(), this.session.today(), '');
    return cap === '' ? null : cents(cap);
  });
  /** The sheet's late percents, dated: for each full 30 days a claim is overdue, the one in force on
   *  that boundary date (its due-by plus 30, 60, 90 ... days) is what it gains of its figure. */
  protected readonly latePcts = signal<DatedValue[]>([]);
  /** The sheet's policy date (blank: its today): a claim dated before it rounds half up, else half to even. */
  protected readonly policyDate = signal('');
  /** What works out an overdue claim's late charge on the sheet's today. */
  private readonly lateness = computed<Lateness>(() => ({
    latePcts: this.latePcts(),
    today: this.session.today(),
    policyDate: this.policyDate(),
  }));
  /** The due-by (which places it in a period) and figure of each claim that has a figure, and whether it counts by its status at
   *  the end of a day, for the periods' due-totals. */
  protected readonly dues = computed(() => {
    const out: DatedDue[] = [];
    const today = this.session.today();
    for (const c of this.claims()) {
      const p = this.peopleById().get(c.personId);
      if (p === undefined) continue;
      const due = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c));
      if (due === null) continue;
      // a hold takes out only a claim that is open now as well
      const countsAt = (day: string): boolean => {
        const status = statusAt(c, day);
        return status !== null && (isOpen(c) ? countsFor(p, { ...c, status }, today)
          : countsFor(undefined, { ...c, status }, today));
      };
      out.push({ personId: c.personId, date: c.dueBy, cents: due, countsAt });
    }
    return out;
  });
  /** Each person's statements, by person id. */
      if (!isOpen(c) || !countsFor(p, c, today)) continue;
      const age = dayNumber(today) - dayNumber(c.date);
      const figure = chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c)) ?? 0;
      aged[age <= 30 ? 0 : age <= 60 ? 1 : 2] += figure;
    }
    return aged;
  }

  /** The person's overdue claims that count: how many, and the sum of their figures in whole cents. */
  protected overdueOf(p: Person): { count: number; cents: number } {
    const today = this.session.today();
    const late = this.claimsOf(p.id).filter((c) => countsFor(p, c, this.session.today()) && overdue(c, today));
    return {
      count: late.length,
      cents: late.reduce((sum, c) => sum + (chargedDueCents(c, this.rates(), gradeOn(p.grades, c.date), this.floors(), this.lateness(), this.roundOn(c)) ?? 0), 0),
    };
  }

  protected statementOf(personId: number): StatementSummary | undefined {
    return this.statements().get(personId);
  }

